import {readFileSync} from 'node:fs';
import {findUpSync} from 'find-up-simple';
import {parse} from 'ini';
export default function registryUrl(scope){
 const p=findUpSync('.npmrc');
 if(!p) return 'https://registry.npmjs.org/';
 const r=parse(readFileSync(p,'utf8'));
 return r[`${scope}:registry`]||r.registry||'https://registry.npmjs.org/';
}
